using VehicleRentalService.DTOs; using VehicleRentalService.Models; using System; using System.IO; using System.Linq; using System.Web; using System.Web.Http; using System.Data.Entity;
namespace VehicleRentalService.Controllers {
 [Authorize,RoutePrefix("api/vehicles")] public class VehiclesController:ApiController {
  VehicleRentalDbContext db=new VehicleRentalDbContext();
  [HttpGet,Route("")] public IHttpActionResult GetAll(){return Ok(db.Vehicles.Include(x=>x.VehicleCategory).Select(x=>new VehicleDto{Id=x.Id,Name=x.Name,Brand=x.Brand,Model=x.Model,Year=x.Year,RegistrationNo=x.RegistrationNo,DailyRate=x.DailyRate,Available=x.Available,Image=x.Image,VehicleCategoryId=x.VehicleCategoryId,VehicleCategoryName=x.VehicleCategory.Name}).ToList());}
  [HttpGet,Route("{id:int}")] public IHttpActionResult Get(int id){var x=db.Vehicles.Include(v=>v.VehicleCategory).FirstOrDefault(v=>v.Id==id);if(x==null)return NotFound();return Ok(new VehicleDto{Id=x.Id,Name=x.Name,Brand=x.Brand,Model=x.Model,Year=x.Year,RegistrationNo=x.RegistrationNo,DailyRate=x.DailyRate,Available=x.Available,Image=x.Image,VehicleCategoryId=x.VehicleCategoryId,VehicleCategoryName=x.VehicleCategory.Name});}
  [HttpPost,Route("")] public IHttpActionResult Post(VehicleDto m){if(m==null||!ModelState.IsValid)return BadRequest(ModelState);if(!db.VehicleCategories.Any(c=>c.Id==m.VehicleCategoryId))return BadRequest("Invalid VehicleCategoryId.");var x=new Vehicle{Name=m.Name,Brand=m.Brand,Model=m.Model,Year=m.Year,RegistrationNo=m.RegistrationNo,DailyRate=m.DailyRate,Available=m.Available,Image=m.Image,VehicleCategoryId=m.VehicleCategoryId};db.Vehicles.Add(x);db.SaveChanges();return Created("api/vehicles/"+x.Id,x);}
  [HttpPut,Route("{id:int}")] public IHttpActionResult Put(int id,VehicleDto m){if(m==null||!ModelState.IsValid)return BadRequest(ModelState);var x=db.Vehicles.Find(id);if(x==null)return NotFound();x.Name=m.Name;x.Brand=m.Brand;x.Model=m.Model;x.Year=m.Year;x.RegistrationNo=m.RegistrationNo;x.DailyRate=m.DailyRate;x.Available=m.Available;x.Image=m.Image;x.VehicleCategoryId=m.VehicleCategoryId;db.SaveChanges();return Ok(x);}
  [HttpDelete,Route("{id:int}")] public IHttpActionResult Delete(int id){var x=db.Vehicles.Include(v=>v.Rentals).FirstOrDefault(v=>v.Id==id);if(x==null)return NotFound();if(x.Rentals.Any())return BadRequest("Vehicle has rental history and cannot be deleted.");db.Vehicles.Remove(x);db.SaveChanges();return Ok(new{message="Vehicle deleted successfully."});}
  [HttpPost,Route("{id:int}/image")] public IHttpActionResult Image(int id){var x=db.Vehicles.Find(id);if(x==null)return NotFound();var f=HttpContext.Current.Request.Files.Count>0?HttpContext.Current.Request.Files[0]:null;if(f==null||f.ContentLength==0)return BadRequest("No image uploaded.");var ext=Path.GetExtension(f.FileName);var allowed=new[]{".jpg",".jpeg",".png",".gif",".webp"};if(string.IsNullOrWhiteSpace(ext)||!allowed.Contains(ext.ToLower()))return BadRequest("Only image files are allowed.");var folder=HttpContext.Current.Server.MapPath("~/Images");if(!Directory.Exists(folder))Directory.CreateDirectory(folder);var name=id+"_"+Guid.NewGuid()+ext.ToLower();f.SaveAs(Path.Combine(folder,name));x.Image=name;db.SaveChanges();return Ok(new{image=name,url="/Images/"+name});}
  protected override void Dispose(bool d){if(d)db.Dispose();base.Dispose(d);}
 }
}
